public class ProductsController : Controller
{
    private readonly IProductRepository _repo;
    private readonly ProductSummary _summary;

    public ProductsController(IProductRepository repo, ProductSummary summary)
    {
        _repo = repo;
        _summary = summary;
    }

    public IActionResult Index()
    {
        ViewBag.TotalValue = _summary.TotalValue;
        return View(_repo.GetAll());
    }
}

public class SettingsController : Controller
{
    private readonly IConfiguration _config;

    public SettingsController(IConfiguration config) => _config = config;

    public IActionResult Index()
    {
        var appName    = _config["App:Name"];
        var logLevel   = _config["Logging:LogLevel:Default"];
        var connection = _config.GetConnectionString("DefaultConnection");
        return View((appName, logLevel, connection));
    }
}
